import React, { useState } from "react";
import { useNavigate, useLocation } from "react-router-dom";
import Navbar from "../components/navbar";
import "../style.css";
import { apiRequest } from "../api";

// Make sure Bootstrap Icons CSS is loaded in your index.html or main entry:
// <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" />

// ─── Room options (mirrors Services.jsx) ──────────────────────────────────────
const roomOptions = [
  { value: "regular",  label: "Regular Room",  price: "₱350 / 3hrs"     },
  { value: "deluxe",   label: "Deluxe Room",   price: "₱800 / Night"    },
  { value: "luxury",   label: "Luxury Room",   price: "₱1,200 / Night"  },
  { value: "event",    label: "Event Space",   price: "₱10,000 / 12hrs" },
];

// ─── Add-on services ──────────────────────────────────────────────────────────
const addOnOptions = [
  { value: "pool",     label: "Private Pool",  icon: <i className="bi bi-water"></i> },
  { value: "romantic", label: "Romantic Stay", icon: <i className="bi bi-heart-fill"></i> },
  { value: "event",   label: "Event Space", icon: <i className="bi bi-calendar-event"></i> },
];

// ─── Helpers ──────────────────────────────────────────────────────────────────
function today() {
  return new Date().toISOString().split("T")[0];
}

function getRoomLabel(value) {
  return roomOptions.find((r) => r.value === value) || null;
}

// ─── Reservation Page ─────────────────────────────────────────────────────────
export default function Reservation() {
  const navigate = useNavigate();
  const location = useLocation();

  const prefill = location.state || {};

  const [form, setForm] = useState({
    firstName: prefill.firstName || "",
    lastName:  prefill.lastName  || "",
    checkIn:   prefill.checkIn   || today(),
    checkOut:  prefill.checkOut  || "",
    room:      prefill.room      || roomOptions[0].value,
    guests:    prefill.guests    || 1,
    addOns:    prefill.addOns    || [],
  });

  const [submitted, setSubmitted] = useState(false);
  const [errors,    setErrors]    = useState({});
  const [submitError, setSubmitError] = useState("");
  const [submitting, setSubmitting] = useState(false);

  // ── Handlers ────────────────────────────────────────────────────────────────
  function handleChange(e) {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
    setErrors((prev) => ({ ...prev, [name]: "" }));
  }

  function toggleAddOn(value) {
    setForm((prev) => ({
      ...prev,
      addOns: prev.addOns.includes(value)
        ? prev.addOns.filter((a) => a !== value)
        : [...prev.addOns, value],
    }));
  }

  function validate() {
    const e = {};
    if (!form.firstName.trim()) e.firstName = "First name is required.";
    if (!form.lastName.trim())  e.lastName  = "Last name is required.";
    if (!form.checkIn)          e.checkIn   = "Check-in date is required.";
    if (!form.checkOut)         e.checkOut  = "Check-out date is required.";
    if (form.checkOut && form.checkOut <= form.checkIn)
      e.checkOut = "Check-out must be after check-in.";
    if (form.guests < 1) e.guests = "At least 1 guest required.";
    return e;
  }

  async function handleSubmit(e) {
    e.preventDefault();

    const e2 = validate();
    if (Object.keys(e2).length) {
      setErrors(e2);
      return;
    }

    setSubmitError("");
    setSubmitting(true);
    try {
      const { reservation } = await apiRequest("/reservations", {
        method: "POST",
        body: JSON.stringify(form),
      });
      navigate("/payment", {
        state: {
          ...form,
          reservationId: reservation.id,
          reference: reservation.reference,
          totalAmount: reservation.totalAmount,
        },
      });
    } catch (requestError) {
      setSubmitError(requestError.message);
    } finally {
      setSubmitting(false);
    }
  }

  // ── Derived values ───────────────────────────────────────────────────────────
  const selectedRoom   = getRoomLabel(form.room);
  const selectedAddOns = addOnOptions.filter((a) => form.addOns.includes(a.value));

  // ── Success screen ───────────────────────────────────────────────────────────
  if (submitted) {
    return (
      <div className="app-shell">
        <Navbar />
        <div className="res-success-wrapper">
          <div className="contact-success">
            <div className="contact-success-icon">
              <i className="bi bi-stars"></i>
            </div>
            <h3>Reservation Received!</h3>
            <p>
              Thank you, <strong>{form.firstName}</strong>! Your reservation at Villa Tjeozabel
              has been submitted. We'll reach out shortly to confirm your booking.
            </p>
            <button
              className="btn btn-warning mt-3"
              onClick={() => navigate("/")}
            >
              Back to Home
            </button>
            <button
              type="button"
              className="contact-back-link"
              onClick={() => setSubmitted(false)}
              style={{ cursor: "pointer" }}
            >
              Make another reservation
            </button>
          </div>
        </div>
        <footer className="footer">© 2026 Villa Tjeozabel</footer>
      </div>
    );
  }

  // ── Main form ────────────────────────────────────────────────────────────────
  return (
    <div className="app-shell">
      <Navbar />

      {/* HERO BANNER */}
      <div
        className="contact-hero"
        style={{ backgroundImage: "url('/assets/img1.jpg')", marginTop: 0 }}
      >
        <div className="contact-hero-overlay" />
        <div className="contact-hero-text">
          <span className="section-tag">Book Your Stay</span>
          <h1>Make a Reservation</h1>
          <p>Fill in the details below and we'll confirm your booking shortly.</p>
        </div>
      </div>

      {/* PAGE BODY */}
      <div className="contact-page">
        <div className="res-body">

          {/* ── LEFT: FORM ── */}
          <div className="contact-form-wrapper">
            <div className="contact-form-header">
              <span className="section-tag">Reservation Details</span>
              <h2 style={{ marginTop: "10px" }}>Your Information</h2>
              <p className="section-sub" style={{ marginBottom: 0 }}>
                All fields marked <span style={{ color: "var(--orange)" }}>*</span> are required.
              </p>
            </div>

            <form className="contact-form" onSubmit={handleSubmit} noValidate>

              {/* Name row */}
              <div className="contact-form-row">
                <div className="contact-field">
                  <label>First Name <span>*</span></label>
                  <input
                    className="auth-input"
                    type="text"
                    name="firstName"
                    placeholder="Juan"
                    value={form.firstName}
                    onChange={handleChange}
                  />
                  {errors.firstName && <small className="res-error">{errors.firstName}</small>}
                </div>
                <div className="contact-field">
                  <label>Last Name <span>*</span></label>
                  <input
                    className="auth-input"
                    type="text"
                    name="lastName"
                    placeholder="dela Cruz"
                    value={form.lastName}
                    onChange={handleChange}
                  />
                  {errors.lastName && <small className="res-error">{errors.lastName}</small>}
                </div>
              </div>

              {/* Date row */}
              <div className="contact-form-row">
                <div className="contact-field">
                  <label>Check-in Date <span>*</span></label>
                  <input
                    className="auth-input"
                    type="date"
                    name="checkIn"
                    min={today()}
                    value={form.checkIn}
                    onChange={handleChange}
                  />
                  {errors.checkIn && <small className="res-error">{errors.checkIn}</small>}
                </div>
                <div className="contact-field">
                  <label>Check-out Date <span>*</span></label>
                  <input
                    className="auth-input"
                    type="date"
                    name="checkOut"
                    min={form.checkIn || today()}
                    value={form.checkOut}
                    onChange={handleChange}
                  />
                  {errors.checkOut && <small className="res-error">{errors.checkOut}</small>}
                </div>
              </div>

              {/* Room + Guests row */}
              <div className="contact-form-row">
                <div className="contact-field">
                  <label>Room / Package <span>*</span></label>
                  <select
                    className="auth-input contact-select"
                    name="room"
                    value={form.room}
                    onChange={handleChange}
                  >
                    {roomOptions.map((r) => (
                      <option key={r.value} value={r.value}>
                        {r.label} — {r.price}
                      </option>
                    ))}
                  </select>
                </div>
                <div className="contact-field">
                  <label>Number of Guests <span>*</span></label>
                  <input
                    className="auth-input"
                    type="number"
                    name="guests"
                    min={1}
                    max={100}
                    value={form.guests}
                    onChange={handleChange}
                  />
                  {errors.guests && <small className="res-error">{errors.guests}</small>}
                </div>
              </div>

              {/* Add-ons */}
              <div className="contact-field">
                <label>
                  Add-on Services{" "}
                  <span style={{ color: "var(--text-light)", fontWeight: 400 }}>(optional)</span>
                </label>
                <div className="res-addon-buttons">
                  {addOnOptions.map((a) => {
                    const active = form.addOns.includes(a.value);
                    return (
                      <button
                        key={a.value}
                        type="button"
                        className={`res-addon-btn${active ? " active" : ""}`}
                        onClick={() => toggleAddOn(a.value)}
                      >
                        <span>{a.icon}</span>
                        {a.label}
                      </button>
                    );
                  })}
                </div>
              </div>

              {/* Submit */}
              {submitError && <p role="alert" className="res-error">{submitError}</p>}
              <button type="submit" className="auth-btn contact-submit" disabled={submitting}>
                {submitting ? "Saving reservation..." : "Confirm Reservation"}
              </button>

            </form>
          </div>

          {/* ── RIGHT: BOOKING SUMMARY ── */}
          <div className="res-summary-sticky">
            <div className="res-summary-card">

              {/* Header */}
              <div className="res-summary-header">
                <div className="res-summary-header-icon">
                  <i className="bi bi-house-heart-fill"></i>
                </div>
                <div>
                  <p className="res-summary-eyebrow">Booking Summary</p>
                  <p className="res-summary-title">Villa Tjeozabel</p>
                </div>
              </div>

              <hr className="res-summary-divider" />

              {/* Room */}
              <SummaryRow
                label="Room / Package"
                value={selectedRoom?.label || "—"}
                sub={selectedRoom?.price}
              />

              {/* Dates */}
              <SummaryRow label="Check-in"  value={form.checkIn  || "Not set"} />
              <SummaryRow label="Check-out" value={form.checkOut || "Not set"} />

              {/* Guests */}
              <SummaryRow
                label="Guests"
                value={`${form.guests} guest${form.guests > 1 ? "s" : ""}`}
              />

              {/* Add-ons */}
              {selectedAddOns.length > 0 && (
                <>
                  <hr className="res-addon-divider" />
                  <p className="res-addon-heading">Add-ons</p>
                  {selectedAddOns.map((a) => (
                    <div key={a.value} className="res-addon-item">
                      <span>{a.icon}</span>
                      <span>{a.label}</span>
                    </div>
                  ))}
                </>
              )}

              <hr className="res-summary-bottom-divider" />

              <p className="res-summary-note">
                <i className="bi bi-chat-dots-fill me-2"></i>
                Our team will contact you to confirm availability and finalize payment.
              </p>
            </div>

            {/* Back link */}
            <div className="res-back-link-wrapper">
              <button
                type="button"
                className="contact-back-link"
                onClick={() => navigate("/services")}
                style={{ cursor: "pointer" }}
              >
                ← Change services
              </button>
            </div>
          </div>

        </div>
      </div>

      <footer className="footer">© 2026 Villa Tjeozabel</footer>
    </div>
  );
}

// ─── Summary Row ──────────────────────────────────────────────────────────────
function SummaryRow({ label, value, sub }) {
  return (
    <div className="res-summary-row">
      <span className="res-summary-row-label">{label}</span>
      <div className="res-summary-row-value">
        <strong>{value}</strong>
        {sub && <span>{sub}</span>}
      </div>
    </div>
  );
}
